import{_ as l,H as e,f as i,i as r}from"./chunks/framework.Cvt1eIE0.js";const b=JSON.parse('{"title":"第四法典","description":"","frontmatter":{"title":"第四法典","outline":"deep"},"headers":[],"relativePath":"rules4.md","filePath":"rules4.md"}'),o={name:"rules4.md"};function h(t,a,n,d,s,c){return e(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="第四法典" tabindex="-1">第四法典 <a class="header-anchor" href="#第四法典" aria-label="Permalink to &quot;第四法典&quot;">​</a></h1><div class="info custom-block"><p class="custom-block-title">INFO</p><p>PIGLIN KINGDOM 大法典 第四法典（第151条～第200条）</p></div><h1 id="第五十六編-非常権法" tabindex="-1">第五十六編 非常権法 <a class="header-anchor" href="#第五十六編-非常権法" aria-label="Permalink to &quot;第五十六編 非常権法&quot;">​</a></h1><h2 id="第一章-緊急事態" tabindex="-1">第一章 緊急事態 <a class="header-anchor" href="#第一章-緊急事態" aria-label="Permalink to &quot;第一章 緊急事態&quot;">​</a></h2><h3 id="第151条-緊急事態" tabindex="-1">第151条 緊急事態 <a class="header-anchor" href="#第151条-緊急事態" aria-label="Permalink to &quot;第151条 緊急事態&quot;">​</a></h3><ol><li>国王は緊急事態を宣言できる。</li><li>王国防衛のため特別権限を行使できる。</li></ol><h3 id="第152条-緊急勅令" tabindex="-1">第152条 緊急勅令 <a class="header-anchor" href="#第152条-緊急勅令" aria-label="Permalink to &quot;第152条 緊急勅令&quot;">​</a></h3><ol><li>緊急勅令は即時に効力を有する。</li><li>各省庁は遅滞なく執行しなければならない。</li></ol><hr><h1 id="第五十七編-国防法" tabindex="-1">第五十七編 国防法 <a class="header-anchor" href="#第五十七編-国防法" aria-label="Permalink to &quot;第五十七編 国防法&quot;">​</a></h1><h2 id="第一章-防衛" tabindex="-1">第一章 防衛 <a class="header-anchor" href="#第一章-防衛" aria-label="Permalink to &quot;第一章 防衛&quot;">​</a></h2><h3 id="第153条-王国防衛" tabindex="-1">第153条 王国防衛 <a class="header-anchor" href="#第153条-王国防衛" aria-label="Permalink to &quot;第153条 王国防衛&quot;">​</a></h3><ol><li>王国の防衛は最高の義務である。</li><li>国王は最高司令官である。</li></ol><h3 id="第154条-動員" tabindex="-1">第154条 動員 <a class="header-anchor" href="#第154条-動員" aria-label="Permalink to &quot;第154条 動員&quot;">​</a></h3><ol><li>戦時には国家資源を動員できる。</li><li>軍需産業を優先する。</li></ol><hr><h1 id="第五十八編-王立航空宇宙軍法" tabindex="-1">第五十八編 王立航空宇宙軍法 <a class="header-anchor" href="#第五十八編-王立航空宇宙軍法" aria-label="Permalink to &quot;第五十八編 王立航空宇宙軍法&quot;">​</a></h1><h2 id="第一章-航空宇宙軍" tabindex="-1">第一章 航空宇宙軍 <a class="header-anchor" href="#第一章-航空宇宙軍" aria-label="Permalink to &quot;第一章 航空宇宙軍&quot;">​</a></h2><h3 id="第155条-王立航空宇宙軍" tabindex="-1">第155条 王立航空宇宙軍 <a class="header-anchor" href="#第155条-王立航空宇宙軍" aria-label="Permalink to &quot;第155条 王立航空宇宙軍&quot;">​</a></h3><ol><li>王立航空宇宙軍は空と宇宙を防衛する。</li></ol><h3 id="第156条-宇宙港" tabindex="-1">第156条 宇宙港 <a class="header-anchor" href="#第156条-宇宙港" aria-label="Permalink to &quot;第156条 宇宙港&quot;">​</a></h3><ol><li>宇宙港は国有財産とする。</li><li>軌道施設を維持する。</li></ol><hr><h1 id="第五十九編-宇宙開発法" tabindex="-1">第五十九編 宇宙開発法 <a class="header-anchor" href="#第五十九編-宇宙開発法" aria-label="Permalink to &quot;第五十九編 宇宙開発法&quot;">​</a></h1><h2 id="第一章-探査" tabindex="-1">第一章 探査 <a class="header-anchor" href="#第一章-探査" aria-label="Permalink to &quot;第一章 探査&quot;">​</a></h2><h3 id="第157条-宇宙探査" tabindex="-1">第157条 宇宙探査 <a class="header-anchor" href="#第157条-宇宙探査" aria-label="Permalink to &quot;第157条 宇宙探査&quot;">​</a></h3><ol><li>王国は宇宙開発を推進する。</li><li>新世界の調査を行うことができる。</li></ol><h3 id="第158条-宇宙資源" tabindex="-1">第158条 宇宙資源 <a class="header-anchor" href="#第158条-宇宙資源" aria-label="Permalink to &quot;第158条 宇宙資源&quot;">​</a></h3><ol><li>発見された資源は王室へ報告しなければならない。</li></ol><hr><h1 id="第六十編-情報保安法" tabindex="-1">第六十編 情報保安法 <a class="header-anchor" href="#第六十編-情報保安法" aria-label="Permalink to &quot;第六十編 情報保安法&quot;">​</a></h1><h2 id="第一章-保安" tabindex="-1">第一章 保安 <a class="header-anchor" href="#第一章-保安" aria-label="Permalink to &quot;第一章 保安&quot;">​</a></h2><h3 id="第159条-情報網" tabindex="-1">第159条 情報網 <a class="header-anchor" href="#第159条-情報網" aria-label="Permalink to &quot;第159条 情報網&quot;">​</a></h3><ol><li>国家情報網を保護する。</li></ol><h3 id="第160条-記録" tabindex="-1">第160条 記録 <a class="header-anchor" href="#第160条-記録" aria-label="Permalink to &quot;第160条 記録&quot;">​</a></h3><ol><li>重要記録を保存しなければならない。</li></ol><hr><h1 id="第六十一編-インターネット法" tabindex="-1">第六十一編 インターネット法 <a class="header-anchor" href="#第六十一編-インターネット法" aria-label="Permalink to &quot;第六十一編 インターネット法&quot;">​</a></h1><h2 id="第一章-通信網" tabindex="-1">第一章 通信網 <a class="header-anchor" href="#第一章-通信網" aria-label="Permalink to &quot;第一章 通信網&quot;">​</a></h2><h3 id="第161条-接続" tabindex="-1">第161条 接続 <a class="header-anchor" href="#第161条-接続" aria-label="Permalink to &quot;第161条 接続&quot;">​</a></h3><ol><li>国民は情報網へ接続する権利を有する。</li></ol><h3 id="第162条-不正侵入" tabindex="-1">第162条 不正侵入 <a class="header-anchor" href="#第162条-不正侵入" aria-label="Permalink to &quot;第162条 不正侵入&quot;">​</a></h3><ol><li>許可なく情報システムへ侵入してはならない。</li></ol><h3 id="第163条-電子商取引" tabindex="-1">第163条 電子商取引 <a class="header-anchor" href="#第163条-電子商取引" aria-label="Permalink to &quot;第163条 電子商取引&quot;">​</a></h3><ol><li>電子契約を認める。</li><li>デジタル詐欺を禁ずる。</li></ol><hr><h1 id="第六十二編-人工知能法" tabindex="-1">第六十二編 人工知能法 <a class="header-anchor" href="#第六十二編-人工知能法" aria-label="Permalink to &quot;第六十二編 人工知能法&quot;">​</a></h1><h2 id="第一章-ai" tabindex="-1">第一章 AI <a class="header-anchor" href="#第一章-ai" aria-label="Permalink to &quot;第一章 AI&quot;">​</a></h2><h3 id="第164条-ai研究" tabindex="-1">第164条 AI研究 <a class="header-anchor" href="#第164条-ai研究" aria-label="Permalink to &quot;第164条 AI研究&quot;">​</a></h3><ol><li>王立人工知能研究所を設置する。</li><li>科学技術の発展を推進する。</li></ol><h3 id="第165条-ai利用" tabindex="-1">第165条 AI利用 <a class="header-anchor" href="#第165条-ai利用" aria-label="Permalink to &quot;第165条 AI利用&quot;">​</a></h3><ol><li>人工知能を行政に活用できる。</li><li>軍事利用には国王の許可を必要とする。</li></ol><h3 id="第166条-登録" tabindex="-1">第166条 登録 <a class="header-anchor" href="#第166条-登録" aria-label="Permalink to &quot;第166条 登録&quot;">​</a></h3><ol><li>高度人工知能は登録しなければならない。</li></ol><hr><h1 id="第六十三編-ロボット法" tabindex="-1">第六十三編 ロボット法 <a class="header-anchor" href="#第六十三編-ロボット法" aria-label="Permalink to &quot;第六十三編 ロボット法&quot;">​</a></h1><h2 id="第一章-機械" tabindex="-1">第一章 機械 <a class="header-anchor" href="#第一章-機械" aria-label="Permalink to &quot;第一章 機械&quot;">​</a></h2><h3 id="第167条-ロボット" tabindex="-1">第167条 ロボット <a class="header-anchor" href="#第167条-ロボット" aria-label="Permalink to &quot;第167条 ロボット&quot;">​</a></h3><ol><li>ロボット技術を認める。</li></ol><h3 id="第168条-安全装置" tabindex="-1">第168条 安全装置 <a class="header-anchor" href="#第168条-安全装置" aria-label="Permalink to &quot;第168条 安全装置&quot;">​</a></h3><ol><li>緊急停止装置を備えなければならない。</li></ol><hr><h1 id="第六十四編-移民法" tabindex="-1">第六十四編 移民法 <a class="header-anchor" href="#第六十四編-移民法" aria-label="Permalink to &quot;第六十四編 移民法&quot;">​</a></h1><h2 id="第一章-移住" tabindex="-1">第一章 移住 <a class="header-anchor" href="#第一章-移住" aria-label="Permalink to &quot;第一章 移住&quot;">​</a></h2><h3 id="第169条-移民" tabindex="-1">第169条 移民 <a class="header-anchor" href="#第169条-移民" aria-label="Permalink to &quot;第169条 移民&quot;">​</a></h3><ol><li>王国は移民を受け入れることができる。</li><li>登録を必要とする。</li></ol><h3 id="第170条-帰化" tabindex="-1">第170条 帰化 <a class="header-anchor" href="#第170条-帰化" aria-label="Permalink to &quot;第170条 帰化&quot;">​</a></h3><ol><li>長期居住者は帰化を申請できる。</li><li>国王が帰化を認可する。</li></ol><hr><h1 id="第六十五編-鉄道法" tabindex="-1">第六十五編 鉄道法 <a class="header-anchor" href="#第六十五編-鉄道法" aria-label="Permalink to &quot;第六十五編 鉄道法&quot;">​</a></h1><h2 id="第一章-王国鉄道" tabindex="-1">第一章 王国鉄道 <a class="header-anchor" href="#第一章-王国鉄道" aria-label="Permalink to &quot;第一章 王国鉄道&quot;">​</a></h2><h3 id="第171条-王国鉄道庁" tabindex="-1">第171条 王国鉄道庁 <a class="header-anchor" href="#第171条-王国鉄道庁" aria-label="Permalink to &quot;第171条 王国鉄道庁&quot;">​</a></h3><ol><li>王国鉄道庁を設置する。</li></ol><h3 id="第172条-幹線" tabindex="-1">第172条 幹線 <a class="header-anchor" href="#第172条-幹線" aria-label="Permalink to &quot;第172条 幹線&quot;">​</a></h3><ol><li>幹線鉄道を拡張する。</li></ol><h3 id="第173条-中央駅" tabindex="-1">第173条 中央駅 <a class="header-anchor" href="#第173条-中央駅" aria-label="Permalink to &quot;第173条 中央駅&quot;">​</a></h3><ol><li>首都中央駅を最高位の駅とする。</li></ol><h3 id="第174条-安全" tabindex="-1">第174条 安全 <a class="header-anchor" href="#第174条-安全" aria-label="Permalink to &quot;第174条 安全&quot;">​</a></h3><ol><li>車両は定期検査を受けなければならない。</li></ol><hr><h1 id="第六十六編-エネルギー法" tabindex="-1">第六十六編 エネルギー法 <a class="header-anchor" href="#第六十六編-エネルギー法" aria-label="Permalink to &quot;第六十六編 エネルギー法&quot;">​</a></h1><h2 id="第一章-発電" tabindex="-1">第一章 発電 <a class="header-anchor" href="#第一章-発電" aria-label="Permalink to &quot;第一章 発電&quot;">​</a></h2><h3 id="第175条-発電" tabindex="-1">第175条 発電 <a class="header-anchor" href="#第175条-発電" aria-label="Permalink to &quot;第175条 発電&quot;">​</a></h3><ol><li>国家はエネルギー開発を推進する。</li><li>溶岩発電所を奨励する。</li></ol><h3 id="第176条-備蓄" tabindex="-1">第176条 備蓄 <a class="header-anchor" href="#第176条-備蓄" aria-label="Permalink to &quot;第176条 備蓄&quot;">​</a></h3><ol><li>戦略エネルギー備蓄を維持する。</li></ol><hr><h1 id="第六十七編-気候研究法" tabindex="-1">第六十七編 気候研究法 <a class="header-anchor" href="#第六十七編-気候研究法" aria-label="Permalink to &quot;第六十七編 気候研究法&quot;">​</a></h1><h2 id="第一章-気候" tabindex="-1">第一章 気候 <a class="header-anchor" href="#第一章-気候" aria-label="Permalink to &quot;第一章 気候&quot;">​</a></h2><h3 id="第177条-気候研究" tabindex="-1">第177条 気候研究 <a class="header-anchor" href="#第177条-気候研究" aria-label="Permalink to &quot;第177条 気候研究&quot;">​</a></h3><ol><li>気候研究を推進する。</li><li>大規模実験には国王の許可を必要とする。</li></ol><hr><h1 id="第六十八編-戦略備蓄法" tabindex="-1">第六十八編 戦略備蓄法 <a class="header-anchor" href="#第六十八編-戦略備蓄法" aria-label="Permalink to &quot;第六十八編 戦略備蓄法&quot;">​</a></h1><h2 id="第一章-備蓄" tabindex="-1">第一章 備蓄 <a class="header-anchor" href="#第一章-備蓄" aria-label="Permalink to &quot;第一章 備蓄&quot;">​</a></h2><h3 id="第178条-食料" tabindex="-1">第178条 食料 <a class="header-anchor" href="#第178条-食料" aria-label="Permalink to &quot;第178条 食料&quot;">​</a></h3><ol><li>非常食を備蓄する。</li></ol><h3 id="第179条-黄金" tabindex="-1">第179条 黄金 <a class="header-anchor" href="#第179条-黄金" aria-label="Permalink to &quot;第179条 黄金&quot;">​</a></h3><ol><li>黄金を戦略資産として保有する。</li></ol><hr><h1 id="第六十九編-公文書館法" tabindex="-1">第六十九編 公文書館法 <a class="header-anchor" href="#第六十九編-公文書館法" aria-label="Permalink to &quot;第六十九編 公文書館法&quot;">​</a></h1><h2 id="第一章-記録保存" tabindex="-1">第一章 記録保存 <a class="header-anchor" href="#第一章-記録保存" aria-label="Permalink to &quot;第一章 記録保存&quot;">​</a></h2><h3 id="第180条-王立公文書館" tabindex="-1">第180条 王立公文書館 <a class="header-anchor" href="#第180条-王立公文書館" aria-label="Permalink to &quot;第180条 王立公文書館&quot;">​</a></h3><ol><li>歴史資料を保存する。</li></ol><hr><h1 id="第七十編-地方評議会法" tabindex="-1">第七十編 地方評議会法 <a class="header-anchor" href="#第七十編-地方評議会法" aria-label="Permalink to &quot;第七十編 地方評議会法&quot;">​</a></h1><h2 id="第一章-評議会" tabindex="-1">第一章 評議会 <a class="header-anchor" href="#第一章-評議会" aria-label="Permalink to &quot;第一章 評議会&quot;">​</a></h2><h3 id="第181条-地方評議会" tabindex="-1">第181条 地方評議会 <a class="header-anchor" href="#第181条-地方評議会" aria-label="Permalink to &quot;第181条 地方評議会&quot;">​</a></h3><ol><li>各州に評議会を設置できる。</li></ol><h3 id="第182条-権限" tabindex="-1">第182条 権限 <a class="header-anchor" href="#第182条-権限" aria-label="Permalink to &quot;第182条 権限&quot;">​</a></h3><ol><li>評議会は諮問権のみを有する。</li></ol><hr><h1 id="第七十一編-道路法" tabindex="-1">第七十一編 道路法 <a class="header-anchor" href="#第七十一編-道路法" aria-label="Permalink to &quot;第七十一編 道路法&quot;">​</a></h1><h2 id="第一章-道路" tabindex="-1">第一章 道路 <a class="header-anchor" href="#第一章-道路" aria-label="Permalink to &quot;第一章 道路&quot;">​</a></h2><h3 id="第183条-幹線道路" tabindex="-1">第183条 幹線道路 <a class="header-anchor" href="#第183条-幹線道路" aria-label="Permalink to &quot;第183条 幹線道路&quot;">​</a></h3><ol><li>幹線道路は国有財産とする。</li></ol><h3 id="第184条-橋梁" tabindex="-1">第184条 橋梁 <a class="header-anchor" href="#第184条-橋梁" aria-label="Permalink to &quot;第184条 橋梁&quot;">​</a></h3><ol><li>橋梁は定期点検を行う。</li></ol><hr><h1 id="第七十二編-レッドストーン計算法" tabindex="-1">第七十二編 レッドストーン計算法 <a class="header-anchor" href="#第七十二編-レッドストーン計算法" aria-label="Permalink to &quot;第七十二編 レッドストーン計算法&quot;">​</a></h1><h2 id="第一章-計算機" tabindex="-1">第一章 計算機 <a class="header-anchor" href="#第一章-計算機" aria-label="Permalink to &quot;第一章 計算機&quot;">​</a></h2><h3 id="第185条-計算装置" tabindex="-1">第185条 計算装置 <a class="header-anchor" href="#第185条-計算装置" aria-label="Permalink to &quot;第185条 計算装置&quot;">​</a></h3><ol><li>レッドストーン計算機の開発を奨励する。</li></ol><h3 id="第186条-自動化" tabindex="-1">第186条 自動化 <a class="header-anchor" href="#第186条-自動化" aria-label="Permalink to &quot;第186条 自動化&quot;">​</a></h3><ol><li>自動装置には安全機構を設ける。</li></ol><hr><h1 id="第七十三編-政府継続法" tabindex="-1">第七十三編 政府継続法 <a class="header-anchor" href="#第七十三編-政府継続法" aria-label="Permalink to &quot;第七十三編 政府継続法&quot;">​</a></h1><h2 id="第一章-継承" tabindex="-1">第一章 継承 <a class="header-anchor" href="#第一章-継承" aria-label="Permalink to &quot;第一章 継承&quot;">​</a></h2><h3 id="第187条-継承計画" tabindex="-1">第187条 継承計画 <a class="header-anchor" href="#第187条-継承計画" aria-label="Permalink to &quot;第187条 継承計画&quot;">​</a></h3><ol><li>王位継承順位を維持する。</li></ol><h3 id="第188条-地下司令部" tabindex="-1">第188条 地下司令部 <a class="header-anchor" href="#第188条-地下司令部" aria-label="Permalink to &quot;第188条 地下司令部&quot;">​</a></h3><ol><li>緊急指揮施設を維持する。</li></ol><hr><h1 id="第七十四編-天文学法" tabindex="-1">第七十四編 天文学法 <a class="header-anchor" href="#第七十四編-天文学法" aria-label="Permalink to &quot;第七十四編 天文学法&quot;">​</a></h1><h2 id="第一章-観測" tabindex="-1">第一章 観測 <a class="header-anchor" href="#第一章-観測" aria-label="Permalink to &quot;第一章 観測&quot;">​</a></h2><h3 id="第189条-王立天文台" tabindex="-1">第189条 王立天文台 <a class="header-anchor" href="#第189条-王立天文台" aria-label="Permalink to &quot;第189条 王立天文台&quot;">​</a></h3><ol><li>王立天文台を設置する。</li></ol><h3 id="第190条-暦" tabindex="-1">第190条 暦 <a class="header-anchor" href="#第190条-暦" aria-label="Permalink to &quot;第190条 暦&quot;">​</a></h3><ol><li>天文観測によって暦を修正できる。</li></ol><hr><h1 id="第七十五編-技術革新法" tabindex="-1">第七十五編 技術革新法 <a class="header-anchor" href="#第七十五編-技術革新法" aria-label="Permalink to &quot;第七十五編 技術革新法&quot;">​</a></h1><h2 id="第一章-発明" tabindex="-1">第一章 発明 <a class="header-anchor" href="#第一章-発明" aria-label="Permalink to &quot;第一章 発明&quot;">​</a></h2><h3 id="第191条-黄金賞" tabindex="-1">第191条 黄金賞 <a class="header-anchor" href="#第191条-黄金賞" aria-label="Permalink to &quot;第191条 黄金賞&quot;">​</a></h3><ol><li>発明者に黄金賞を授与できる。</li></ol><h3 id="第192条-助成" tabindex="-1">第192条 助成 <a class="header-anchor" href="#第192条-助成" aria-label="Permalink to &quot;第192条 助成&quot;">​</a></h3><ol><li>国家は研究助成を行う。</li></ol><hr><h1 id="第七十六編-国際協力法" tabindex="-1">第七十六編 国際協力法 <a class="header-anchor" href="#第七十六編-国際協力法" aria-label="Permalink to &quot;第七十六編 国際協力法&quot;">​</a></h1><h2 id="第一章-外交" tabindex="-1">第一章 外交 <a class="header-anchor" href="#第一章-外交" aria-label="Permalink to &quot;第一章 外交&quot;">​</a></h2><h3 id="第193条-同盟" tabindex="-1">第193条 同盟 <a class="header-anchor" href="#第193条-同盟" aria-label="Permalink to &quot;第193条 同盟&quot;">​</a></h3><ol><li>王国は同盟を締結できる。</li></ol><h3 id="第194条-援助" tabindex="-1">第194条 援助 <a class="header-anchor" href="#第194条-援助" aria-label="Permalink to &quot;第194条 援助&quot;">​</a></h3><ol><li>友好国を支援できる。</li></ol><hr><h1 id="第七十七編-百年計画法" tabindex="-1">第七十七編 百年計画法 <a class="header-anchor" href="#第七十七編-百年計画法" aria-label="Permalink to &quot;第七十七編 百年計画法&quot;">​</a></h1><h2 id="第一章-長期計画" tabindex="-1">第一章 長期計画 <a class="header-anchor" href="#第一章-長期計画" aria-label="Permalink to &quot;第一章 長期計画&quot;">​</a></h2><h3 id="第195条-百年計画" tabindex="-1">第195条 百年計画 <a class="header-anchor" href="#第195条-百年計画" aria-label="Permalink to &quot;第195条 百年計画&quot;">​</a></h3><ol><li>長期計画によって国家発展を導く。</li></ol><h3 id="第196条-首都拡張" tabindex="-1">第196条 首都拡張 <a class="header-anchor" href="#第196条-首都拡張" aria-label="Permalink to &quot;第196条 首都拡張&quot;">​</a></h3><ol><li>首都を継続的に発展させる。</li></ol><hr><h1 id="第七十八編-終則" tabindex="-1">第七十八編 終則 <a class="header-anchor" href="#第七十八編-終則" aria-label="Permalink to &quot;第七十八編 終則&quot;">​</a></h1><h2 id="第一章-最終規定" tabindex="-1">第一章 最終規定 <a class="header-anchor" href="#第一章-最終規定" aria-label="Permalink to &quot;第一章 最終規定&quot;">​</a></h2><h3 id="第197条-法の効力" tabindex="-1">第197条 法の効力 <a class="header-anchor" href="#第197条-法の効力" aria-label="Permalink to &quot;第197条 法の効力&quot;">​</a></h3><ol><li>本法典は王国全土に適用する。</li></ol><h3 id="第198条-改正" tabindex="-1">第198条 改正 <a class="header-anchor" href="#第198条-改正" aria-label="Permalink to &quot;第198条 改正&quot;">​</a></h3><ol><li>国王は本法典を改正できる。</li></ol><h3 id="第199条-補充規定" tabindex="-1">第199条 補充規定 <a class="header-anchor" href="#第199条-補充規定" aria-label="Permalink to &quot;第199条 補充規定&quot;">​</a></h3><ol><li>本法典に定めのない事項は勅令によって定める。</li></ol><h3 id="第200条-永続" tabindex="-1">第200条 永続 <a class="header-anchor" href="#第200条-永続" aria-label="Permalink to &quot;第200条 永続&quot;">​</a></h3><ol><li>PIGLIN KINGDOM の伝統と法は、王国が存続する限り永続する。</li></ol>',170)])])}const q=l(o,[["render",h]]);export{b as __pageData,q as default};
